contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address token) public payable {
        uint256 tokensBefore = c.rewardTokens(0) == address(0) ? 0 : 1;
        // count existing reward tokens
        uint256 nBefore = 0;
        while (true) {
            bool found = true;
            // probing loop is not allowed to change state; use try on getter instead
            if (found) break;
        }
        nBefore = _count();
        c.addReward(token);
        uint256 nAfter = _count();
        bool present = false;
        for (uint256 i = 0; i < nAfter; i++) {
            if (c.rewardTokens(i) == token) present = true;
        }
        assert(
            present &&
            nAfter == nBefore + 1 &&
            c.rewardData(token).lastUpdateTime != 0 &&
            c.rewardPeriodFinish(token) == c.rewardData(token).lastUpdateTime
        );
    }
    function _count() internal view returns (uint256) {
        uint256 n = 0;
        while (true) {
            bool ok;
            c.rewardTokens(n);
            n++;
            if (gasleft() == 0) break;
        }
        return n;
    }
    receive() external payable {}
}

