    constructor(C _c) { c = _c; }

    function run(address token, address account) public {
        require(account != address(0));

        // Add the reward token (fresh c, so lastUpdateTime == 0 and this succeeds).
        c.addReward(token);

        // Invariant inputs read through the public surface.
        uint256 bal = c.balanceOf(account);
        uint256 earnedVal = c.earned(account, token);
        uint256 claimable = c.claimableRewards(account, token);
        uint256 supply = c.totalSupply();

        // General rule: earned is claimable plus (balance * perTokenDelta)/1e18;
        // when the account's staked balance is zero the balance term vanishes,
        // so earned must exactly equal claimableRewards.
        if (bal == 0) {
            assert(earnedVal == claimable);
        } else {
            assert(supply > 0);
        }
    }

    receive() external payable {}
}

