contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address token, address otherToken) public payable {
        require(token != address(0), "zero token");
        require(otherToken != token, "tokens must differ");

        // A fresh contract has never seen `token` as a reward token.
        bool doubleAddReverted;
        c.addReward(token);
        try c.addReward(token) {
            doubleAddReverted = false;
        } catch {
            doubleAddReverted = true;
        }

        // An unadded token must have no reward state at all.
        uint256 earnedOther = c.earned(address(this), otherToken);
        uint256 rptOther = c.rewardPerToken(otherToken);
        uint40 finishOther = c.rewardPeriodFinish(otherToken);

        // The newly added token also has zero rewards until notified.
        uint256 earnedToken = c.earned(address(this), token);
        uint256 rptToken = c.rewardPerToken(token);
        uint40 finishToken = c.rewardPeriodFinish(token);

        assert(
            doubleAddReverted
            && earnedOther == 0 && rptOther == 0 && finishOther == 0
            && earnedToken == 0 && rptToken == 0 && finishToken > 0
        );
    }

    receive() external payable {}
}

