contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address account, uint256 amount) public {
        require(amount > 0);
        uint256 balBefore = c.balanceOf(account);
        uint256 tsBefore = c.totalSupply();
        c.stakeFor(account, amount);
        uint256 balMid = c.balanceOf(account);
        uint256 tsMid = c.totalSupply();
        uint256 ethMid = address(c).balance;
        c.withdraw(amount, false);
        uint256 balAfter = c.balanceOf(account);
        uint256 tsAfter = c.totalSupply();
        assert(
            balMid == balBefore + amount &&
            tsMid == tsBefore + amount &&
            ethMid == 0 &&
            balAfter == balBefore &&
            tsAfter == tsBefore
        );
    }
    fallback(bytes calldata) external payable returns (bytes memory) {
        bytes4 sel;
        assembly { sel := calldataload(0) }
        if (
            sel == bytes4(keccak256("transferFrom(address,address,uint256)")) ||
            sel == bytes4(keccak256("transfer(address,uint256)"))
        ) {
            return abi.encode(true);
        }
        return "";
    }
    receive() external payable {}
}

