contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address newDistributor) public {
        require(newDistributor != address(0));
        // this contract is the deployer, hence the initial owner
        c.renounceOwnership();

        bool reverted;
        try c.setRewardDistributor(newDistributor) {
            reverted = false;
        } catch {
            reverted = true;
        }

        assert(reverted && c.owner() == address(0));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address token) public {
        require(token != address(0));
        // precondition: token not yet registered (this contract is the owner)
        (, , uint40 lastUpBefore, ) = c.rewardData(token);
        require(lastUpBefore == 0);

        c.addReward(token);

        (uint40 finish, , uint40 lastUp, ) = c.rewardData(token);

        bool reverted;
        try c.addReward(token) {
            reverted = false;
        } catch {
            reverted = true;
        }

        assert(
            lastUp == block.timestamp &&
            finish == block.timestamp &&
            reverted
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address token, address account) public {
        require(token != address(0));
        // token must not already be registered (lastUpdateTime == 0)
        (, , uint40 lastUpBefore, ) = c.rewardData(token);
        require(lastUpBefore == 0);

        // register the reward token (this contract is the owner)
        c.addReward(token);

        uint256 earnedVal = c.earned(account, token);
        uint256 claimable = c.claimableRewards(account, token);
        uint256 bal = c.balanceOf(account);

        assert(bal == 0 && earnedVal == claimable);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address rewardToken) public {
        (, , uint40 lastUpdateBefore, ) = c.rewardData(rewardToken);
        require(lastUpdateBefore == 0);
        c.addReward(rewardToken);
        (, , uint40 lastUpdateAfter, ) = c.rewardData(rewardToken);
        uint40 finish = c.rewardPeriodFinish(rewardToken);
        assert(lastUpdateAfter == uint40(block.timestamp) && finish == uint40(block.timestamp));
    }
    receive() external payable {}
}
